console.log(params.info);
});

```

elements-sector.keyframeAnimation.description:
关键帧动画配置。支持配置为数组同时使用多个关键帧动画。

示例：

```
keyframeAnimation: [{
// 呼吸效果的缩放动画
duration: 1000,
loop: true,
keyframes: [{
percent: 0.5,
easing: 'sinusoidalInOut',
scaleX: 0.1,
scaleY: 0.1
}, {
percent: 1,
easing: 'sinusoidalInOut',
scaleX: 1,
scaleY: 1
}]
}, {
// 平移动画
duration: 2000,
loop: true,
keyframes: [{
percent: 0,
x: 10
}, {
percent: 1,
x: 100
}]
}]

```

假如一个属性同时被应用了关键帧动画和过渡动画，过渡动画会被忽略。

elements-sector.keyframeAnimation.keyfra.description:
